SELECT /* getActiveCodeCnt */
       COUNT(1)
  FROM TB_CODEXD
 WHERE COMM_CODE = #{commCode}
   AND COMD_CODE = #{comdCode}
   AND USEE_YSNO = #{commYes}

SELECT /* dupComplaint */
       COUNT(1)
  FROM TH_CMPLNT
 WHERE USER_NUMB = #{userNumb}
   AND TAGT_TYPE = #{tagtType}
   AND TAGT_NUMB = #{tagtNumb}
   AND TAGT_HASH = #{tagtHash}

SELECT /* getEvidenceNumb */
       EVDC_NUMB
  FROM TH_CMEVDC
 WHERE TAGT_TYPE = #{tagtType}
   AND TAGT_NUMB = #{tagtNumb}
   AND TAGT_HASH = #{tagtHash}

mapper.insert:
/* setEvidence */
INSERT INTO TH_CMEVDC (
            TAGT_TYPE
          , TAGT_NUMB
          , TAGT_HASH
          , TAGT_USER
          , ORIG_NAME
          , MIME_TYPE
          , FILE_SIZE
          , EVDC_DATA
) VALUES (  #{tagtType}
          , #{tagtNumb}
          , #{tagtHash}
          , #{tagtUser,jdbcType=NUMERIC}
          , #{origName,jdbcType=VARCHAR}
          , #{mimeType}
          , #{fileSize}
          , #{evdcData,jdbcType=LONGVARBINARY}
)


/* setComplaint */
INSERT INTO TH_CMPLNT (
            USER_NUMB
          , TAGT_TYPE
          , TAGT_NUMB
          , TAGT_HASH
          , TAGT_USER
          , TAGT_CNTN
          , EVDC_NUMB
          , CMPL_RSON
          , CMPL_CNTN
          , CMPL_STAT
) VALUES (  #{userNumb}
          , #{complaint.tagtType}
          , #{complaint.tagtNumb}
          , #{complaint.tagtHash}
          , #{complaint.tagtUser}
          , #{complaint.tagtCntn,jdbcType=LONGVARCHAR}
          , #{complaint.evdcNumb,jdbcType=NUMERIC}
          , #{complaint.cmplRson}
          , #{complaint.cmplCntn,jdbcType=VARCHAR}
          , #{complaintStatusReceived}
)

mapper.select:

SELECT /* getAutoActionCmplCnt */
       COUNT(1)
  FROM TH_CMPLNT
 WHERE TAGT_TYPE = #{tagtType}
   AND TAGT_NUMB = #{tagtNumb}
   AND TAGT_HASH = #{tagtHash}
   AND CMPL_STAT != #{complaintStatusRejected}
   FOR UPDATE

mapper.update:

UPDATE /* uptAutoReportPrivate */
       TM_REPORT
   SET PUBC_YSNO = #{commNo}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE REPT_NUMB = #{tagtNumb}
   AND USER_NUMB = #{tagtUser}
   AND PUBC_YSNO = #{commYes}


UPDATE /* delAutoReply */
       TB_REPLXX
   SET DELT_YSNO = #{commYes}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE REPL_NUMB = #{tagtNumb}
   AND USER_NUMB = #{tagtUser}
   AND COALESCE(DELT_YSNO, #{commNo}) = #{commNo}

mapper.insert:
/* setAutoAction */
INSERT INTO TH_CMACTN (
            TAGT_TYPE
          , TAGT_NUMB
          , TAGT_HASH
          , TAGT_USER
          , ACTN_TYPE
          , RSLT_CODE
          , THRS_CNTT
          , CMPL_CNTT
          , ACTN_ORDR
          , TRIG_CMPL
          , RSLT_CNTN
) VALUES (  #{tagtType}
          , #{tagtNumb}
          , #{tagtHash}
          , #{tagtUser,jdbcType=NUMERIC}
          , #{actnType}
          , #{rsltCode}
          , #{thrsCntt}
          , #{cmplCntt}
          , #{actnOrdr}
          , #{trigCmpl,jdbcType=NUMERIC}
          , #{rsltCntn,jdbcType=VARCHAR}
)

mapper.update:

UPDATE /* uptAutoComplaints */
       TH_CMPLNT
   SET CMPL_STAT = #{complaintStatusActioned}
     , PROC_CNTN = #{procCntn}
     , PROC_ADMN = NULL
     , PROC_DATE = CURRENT_TIMESTAMP
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE TAGT_TYPE = #{tagtType}
   AND TAGT_NUMB = #{tagtNumb}
   AND TAGT_HASH = #{tagtHash}
   AND CMPL_STAT IN (#{complaintStatusReceived}, #{complaintStatusReviewing})

mapper.insert:
/* setResultEvent */
INSERT INTO TH_CMREVT (
            ACTN_NUMB, TRIG_CMPL, TAGT_TYPE, TAGT_NUMB, TAGT_HASH, TAGT_USER
          , TAGT_NAME, RSON_SUMM, RSON_CODE, RSON_NAME, ACTN_TYPE
          , RPTR_CNTN, TGTR_CNTN, PROC_DATE
) VALUES (  #{actnNumb,jdbcType=NUMERIC}, #{trigCmpl,jdbcType=NUMERIC}, #{tagtType}
          , #{tagtNumb}, #{tagtHash,jdbcType=CHAR}, #{tagtUser,jdbcType=NUMERIC}
          , #{tagtName}, #{rsonSumm}, #{rsonCode,jdbcType=VARCHAR}, #{rsonName}
          , #{actnType}, #{rptrCntn}, #{tgtrCntn}, #{procDate}
)


INSERT /* setAutoReporterResults */
  INTO TH_CMRSLT (
       EVNT_NUMB, CMPL_NUMB, USER_NUMB, RCVR_TYPE, REGI_DATE
)
SELECT #{eventNumb}, C.CMPL_NUMB, C.USER_NUMB, #{receiverReporter}, CURRENT_TIMESTAMP(6)
  FROM TH_CMPLNT C
  JOIN TM_USERXM U
    ON U.USER_NUMB = C.USER_NUMB
   AND U.USER_STAT IN (#{userStatActive}, #{userStatSuspended})
 WHERE C.TAGT_TYPE = #{tagtType}
   AND C.TAGT_NUMB = #{tagtNumb}
   AND C.TAGT_HASH = #{tagtHash}
   AND C.CMPL_STAT = #{complaintStatusActioned}
   AND C.USER_NUMB IS NOT NULL
   AND NOT EXISTS (
       SELECT 1
         FROM TH_CMRSLT R
        WHERE R.EVNT_NUMB = #{eventNumb}
          AND R.CMPL_NUMB = C.CMPL_NUMB
          AND R.RCVR_TYPE = #{receiverReporter}
       )

mapper.update:

UPDATE /* uptResultConfirm */
       TH_CMRSLT R
  JOIN TM_USERXM U
    ON U.USER_NUMB = R.USER_NUMB
   SET R.CONF_DATE = CURRENT_TIMESTAMP(6)
 WHERE R.USER_NUMB = #{userNumb}
   AND R.RSLT_NUMB <= #{resultNumb}
   AND R.CONF_DATE IS NULL
   AND U.USER_STAT = #{userStatActive}
